SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2007.YEAR, Станции2007.NUST, Станции2007.E, Станции2007.EOTP, Станции2007.EURT, Станции2007.EUST, Станции2007.Q, Станции2007.TURT, Станции2007.TUST, Станции2007.B, Станции2007.GAZ, Доп_угли2007.gazpp, Станции2007.MAZUT, Станции2007.TORF, Станции2007.SLAN, Станции2007.GTT, Станции2007.PROCH, Станции2007.UGOL, Станции2007.DON, Станции2007.PODM, Станции2007.PECH, Доп_угли2007.int, Доп_угли2007.vork, Станции2007.ARKT, Станции2007.KUZN, Станции2007.URAL, Доп_угли2007.sver, Доп_угли2007.chel, Доп_угли2007.kizel, Станции2007.BASHK, Станции2007.EKIB, Станции2007.KARAG, Станции2007.KAN, Доп_угли2007.nazar, Доп_угли2007.ibor, Доп_угли2007.berez, Доп_угли2007.per, Станции2007.IRKUT, Доп_угли2007.azey, Доп_угли2007.mug, Доп_угли2007.cher, Доп_угли2007.jer, Станции2007.HAK, Станции2007.TUV, Станции2007.BUR, Доп_угли2007.gusin, Доп_угли2007.tugn, Станции2007.CHIT, Доп_угли2007.har, Доп_угли2007.urt, Станции2007.[YAKUT] AS Выражение1, Доп_угли2007.neru, Доп_угли2007.pyak, Станции2007.[AMUR] AS Выражение2, Доп_угли2007.rai, Доп_угли2007.erk, Станции2007.URG, Станции2007.PRIM, Станции2007.LUCH, Станции2007.MAG, Станции2007.SAH, Станции2007.USHUM, Станции2007.QOTR, Станции2007.SNK, Станции2007.EWTP, Станции2007.NT, Станции2007.OBOR, Станции2007.VED, Станции2007.OBL, Станции2007.DEP, Станции2007.OES, Станции2007.ER, Станции2007.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Станции2007.NTsum, Станции2007.GK, Станции2007.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM ((((((Станции2007 INNER JOIN Имена_станций ON Станции2007.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2007.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2007.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2007 ON (Станции2007.YEAR=Доп_угли2007.YEAR) AND (Станции2007.NUMB1120=Доп_угли2007.NUMB1120)) LEFT JOIN имена_ГК ON Станции2007.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2007.BE=имена_БЕ.code) LEFT JOIN Города ON Имена_станций.codegor=Города.code;
